   193	/**
   194	  push a general string onto the wire
   195	*/
   196	_PUBLIC_ enum ndr_err_code ndr_push_string(struct ndr_push *ndr, int ndr_flags, const char *s)
   197	{
   198	        ssize_t s_len, c_len;
   199	        size_t d_len;
   200	        int do_convert = 1, chset = CH_UTF16;
   201	        unsigned flags = ndr->flags;
   202	        unsigned byte_mul = 2;
   203	        uint8_t *dest = NULL;
   204	
   205	        if (!(ndr_flags & NDR_SCALARS)) {
   206	                return NDR_ERR_SUCCESS;
   207	        }
   208	
   209	        if (NDR_BE(ndr)) {
   210	                chset = CH_UTF16BE;
   211	        }
   212	        
   213	        s_len = s?strlen(s):0;
   214	
   215	        if (flags & LIBNDR_FLAG_STR_ASCII) {
   216	                chset = CH_DOS;
   217	                byte_mul = 1;
   218	                flags &= ~LIBNDR_FLAG_STR_ASCII;
   219	        }
   220	
   221	        if (flags & LIBNDR_FLAG_STR_UTF8) {
   222	                chset = CH_UTF8;
   223	                byte_mul = 1;
   224	                flags &= ~LIBNDR_FLAG_STR_UTF8;
   225	        }
   226	
   227	        if (flags & LIBNDR_FLAG_STR_RAW8) {
   228	                do_convert = 0;
   229	                byte_mul = 1;
   230	                flags &= ~LIBNDR_FLAG_STR_RAW8;
   231	        }
   232	
   233	        flags &= ~LIBNDR_FLAG_STR_CONFORMANT;
   234	
   235	        if (!(flags & LIBNDR_FLAG_STR_NOTERM)) {
   236	                s_len++;
   237	        }
   238	
   239	        if (!do_convert) {
   240	                d_len = s_len;
   241	                dest = (uint8_t *)talloc_strndup(ndr, s, s_len);
   242	        } else if (!convert_string_talloc(ndr, CH_UNIX, chset, s, s_len,
   243	                                   (void **)(void *)&dest, &d_len))
   244	        {
   245	                return ndr_push_error(ndr, NDR_ERR_CHARCNV, 
   246	                                      "Bad character push conversion with flags 0x%x", flags);
   247	        }
   248	
   249	        if (flags & LIBNDR_FLAG_STR_BYTESIZE) {
   250	                c_len = d_len;
   251	                flags &= ~LIBNDR_FLAG_STR_BYTESIZE;
   252	        } else if (flags & LIBNDR_FLAG_STR_CHARLEN) {
   253	                c_len = (d_len / byte_mul)-1;
   254	                flags &= ~LIBNDR_FLAG_STR_CHARLEN;
   255	        } else {
   256	                c_len = d_len / byte_mul;
   257	        }
   258	
   259	        switch ((flags & LIBNDR_STRING_FLAGS) & ~LIBNDR_FLAG_STR_NOTERM) {
   260	        case LIBNDR_FLAG_STR_LEN4|LIBNDR_FLAG_STR_SIZE4:
   261	                NDR_CHECK(ndr_push_uint32(ndr, NDR_SCALARS, c_len));
   262	                NDR_CHECK(ndr_push_uint32(ndr, NDR_SCALARS, 0));
   263	                NDR_CHECK(ndr_push_uint32(ndr, NDR_SCALARS, c_len));
   264	                NDR_CHECK(ndr_push_bytes(ndr, dest, d_len));
   265	                break;
   266	
   267	        case LIBNDR_FLAG_STR_LEN4:
   268	                NDR_CHECK(ndr_push_uint32(ndr, NDR_SCALARS, 0));
   269	                NDR_CHECK(ndr_push_uint32(ndr, NDR_SCALARS, c_len));
   270	                NDR_CHECK(ndr_push_bytes(ndr, dest, d_len));
   271	                break;
   272	
   273	        case LIBNDR_FLAG_STR_SIZE4:
   274	                NDR_CHECK(ndr_push_uint32(ndr, NDR_SCALARS, c_len));
   275	                NDR_CHECK(ndr_push_bytes(ndr, dest, d_len));
   276	                break;
   277	
   278	        case LIBNDR_FLAG_STR_SIZE2:
   279	                NDR_CHECK(ndr_push_uint16(ndr, NDR_SCALARS, c_len));
   280	                NDR_CHECK(ndr_push_bytes(ndr, dest, d_len));
   281	                break;
   282	
   283	        case LIBNDR_FLAG_STR_NULLTERM:
   284	                NDR_CHECK(ndr_push_bytes(ndr, dest, d_len));
   285	                break;
   286	
   287	        default:
   288	                if (ndr->flags & LIBNDR_FLAG_REMAINING) {
   289	                        NDR_CHECK(ndr_push_bytes(ndr, dest, d_len));
   290	                        break;          
   291	                }
   292	
   293	                return ndr_push_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x\n",
   294	                                      ndr->flags & LIBNDR_STRING_FLAGS);
   295	        }
   296	
   297	        talloc_free(dest);
   298	
   299	        return NDR_ERR_SUCCESS;
   300	}
