   302	/**
   303	  push a general string onto the wire
   304	*/
   305	_PUBLIC_ size_t ndr_string_array_size(struct ndr_push *ndr, const char *s)
   306	{
   307	        size_t c_len;
   308	        unsigned flags = ndr->flags;
   309	        unsigned byte_mul = 2;
   310	        unsigned c_len_term = 1;
   311	
   312	        if (flags & LIBNDR_FLAG_STR_RAW8) {
   313	                c_len = s?strlen(s):0;
   314	        } else {
   315	                c_len = s?strlen_m(s):0;
   316	        }
   317	
   318	        if (flags & (LIBNDR_FLAG_STR_ASCII|LIBNDR_FLAG_STR_RAW8|LIBNDR_FLAG_STR_UTF8)) {
   319	                byte_mul = 1;
   320	        }
   321	
   322	        if (flags & LIBNDR_FLAG_STR_NOTERM) {
   323	                c_len_term = 0;
   324	        }
   325	
   326	        c_len = c_len + c_len_term;
   327	
   328	        if (flags & LIBNDR_FLAG_STR_BYTESIZE) {
   329	                c_len = c_len * byte_mul;
   330	        }
   331	
   332	        return c_len;
   333	}
