   335	_PUBLIC_ void ndr_print_string(struct ndr_print *ndr, const char *name, const char *s)
   336	{
   337	        if (s) {
   338	                ndr->print(ndr, "%-25s: '%s'", name, s);
   339	        } else {
   340	                ndr->print(ndr, "%-25s: NULL", name);
   341	        }
   342	}
