   344	_PUBLIC_ uint32_t ndr_size_string(int ret, const char * const* string, int flags) 
   345	{
   346	        /* FIXME: Is this correct for all strings ? */
   347	        if(!(*string)) return ret;
   348	        return ret+strlen(*string)+1;
