   351	/**
   352	  pull a general string array from the wire
   353	*/
   354	_PUBLIC_ enum ndr_err_code ndr_pull_string_array(struct ndr_pull *ndr, int ndr_flags, const char ***_a)
   355	{
   356	        const char **a = NULL;
   357	        uint32_t count;
   358	        unsigned flags = ndr->flags;
   359	        unsigned saved_flags = ndr->flags;
   360	
   361	        if (!(ndr_flags & NDR_SCALARS)) {
   362	                return NDR_ERR_SUCCESS;
   363	        }
   364	
   365	        switch (flags & (LIBNDR_FLAG_STR_NULLTERM|LIBNDR_FLAG_STR_NOTERM)) {
   366	        case LIBNDR_FLAG_STR_NULLTERM:
   367	                /* 
   368	                 * here the strings are null terminated
   369	                 * but also the array is null terminated if LIBNDR_FLAG_REMAINING
   370	                 * is specified
   371	                 */
   372	                for (count = 0;; count++) {
   373	                        TALLOC_CTX *tmp_ctx;
   374	                        const char *s = NULL;
   375	                        a = talloc_realloc(ndr->current_mem_ctx, a, const char *, count + 2);
   376	                        NDR_ERR_HAVE_NO_MEMORY(a);
   377	                        a[count]   = NULL;
   378	                        a[count+1]   = NULL;
   379	
   380	                        tmp_ctx = ndr->current_mem_ctx;
   381	                        ndr->current_mem_ctx = a;
   382	                        NDR_CHECK(ndr_pull_string(ndr, ndr_flags, &s));
   383	                        if ((ndr->data_size - ndr->offset) == 0 && ndr->flags & LIBNDR_FLAG_REMAINING)
   384	                        {
   385	                                a[count] = s;
   386	                                break;
   387	                        }
   388	                        ndr->current_mem_ctx = tmp_ctx;
   389	                        if (strcmp("", s)==0) {
   390	                                a[count] = NULL;
   391	                                break;
   392	                        } else {
   393	                                a[count] = s;
   394	                        }
   395	                }
   396	
   397	                *_a =a;
   398	                break;
   399	
   400	        case LIBNDR_FLAG_STR_NOTERM:
   401	                if (!(ndr->flags & LIBNDR_FLAG_REMAINING)) {
   402	                        return ndr_pull_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x (missing NDR_REMAINING)\n",
   403	                                              ndr->flags & LIBNDR_STRING_FLAGS);
   404	                }
   405	                /*
   406	                 * here the strings are not null terminated
   407	                 * but serarated by a null terminator
   408	                 *
   409	                 * which means the same as:
   410	                 * Every string is null terminated exept the last
   411	                 * string is terminated by the end of the buffer
   412	                 *
   413	                 * as LIBNDR_FLAG_STR_NULLTERM also end at the end
   414	                 * of the buffer, we can pull each string with this flag
   415	                 *
   416	                 * The big difference with the case LIBNDR_FLAG_STR_NOTERM +
   417	                 * LIBNDR_FLAG_REMAINING is that the last string will not be null terminated
   418	                 */
   419	                ndr->flags &= ~(LIBNDR_FLAG_STR_NOTERM|LIBNDR_FLAG_REMAINING);
   420	                ndr->flags |= LIBNDR_FLAG_STR_NULLTERM;
   421	
   422	                for (count = 0; ((ndr->data_size - ndr->offset) > 0); count++) {
   423	                        TALLOC_CTX *tmp_ctx;
   424	                        const char *s = NULL;
   425	                        a = talloc_realloc(ndr->current_mem_ctx, a, const char *, count + 2);
   426	                        NDR_ERR_HAVE_NO_MEMORY(a);
   427	                        a[count]   = NULL;
   428	                        a[count+1]   = NULL;
   429	
   430	                        tmp_ctx = ndr->current_mem_ctx;
   431	                        ndr->current_mem_ctx = a;
   432	                        NDR_CHECK(ndr_pull_string(ndr, ndr_flags, &s));
   433	                        ndr->current_mem_ctx = tmp_ctx;
   434	                        a[count] = s;
   435	                }
   436	
   437	                *_a =a;
   438	                break;
   439	
   440	        default:
   441	                return ndr_pull_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x\n",
   442	                                      ndr->flags & LIBNDR_STRING_FLAGS);
   443	        }
   444	
   445	        ndr->flags = saved_flags;
   446	        return NDR_ERR_SUCCESS;
   447	}
   448	
   449	/**
   450	  push a general string array onto the wire
   451	*/
   452	_PUBLIC_ enum ndr_err_code ndr_push_string_array(struct ndr_push *ndr, int ndr_flags, const char **a)
   453	{
   454	        uint32_t count;
   455	        unsigned flags = ndr->flags;
   456	        unsigned saved_flags = ndr->flags;
   457	
   458	        if (!(ndr_flags & NDR_SCALARS)) {
   459	                return NDR_ERR_SUCCESS;
   460	        }
   461	
   462	        switch (flags & LIBNDR_STRING_FLAGS) {
   463	        case LIBNDR_FLAG_STR_NULLTERM:
   464	                for (count = 0; a && a[count]; count++) {
   465	                        NDR_CHECK(ndr_push_string(ndr, ndr_flags, a[count]));
   466	                }
   467	                /* If LIBNDR_FLAG_REMAINING then we do not add a null terminator to the array */
   468	                if (!(flags & LIBNDR_FLAG_REMAINING))
   469	                {
   470	                        NDR_CHECK(ndr_push_string(ndr, ndr_flags, ""));
   471	                }
   472	                break;
   473	
   474	        case LIBNDR_FLAG_STR_NOTERM:
   475	                if (!(ndr->flags & LIBNDR_FLAG_REMAINING)) {
   476	                        return ndr_push_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x (missing NDR_REMAINING)\n",
   477	                                              ndr->flags & LIBNDR_STRING_FLAGS);
   478	                }
   479	
   480	                for (count = 0; a && a[count]; count++) {
   481	                        if (count > 0) {
   482	                                ndr->flags &= ~(LIBNDR_FLAG_STR_NOTERM|LIBNDR_FLAG_REMAINING);
   483	                                ndr->flags |= LIBNDR_FLAG_STR_NULLTERM;
   484	                                NDR_CHECK(ndr_push_string(ndr, ndr_flags, ""));
   485	                                ndr->flags = saved_flags;
   486	                        }
   487	                        NDR_CHECK(ndr_push_string(ndr, ndr_flags, a[count]));
   488	                }
   489	
   490	                break;
   491	
   492	        default:
   493	                return ndr_push_error(ndr, NDR_ERR_STRING, "Bad string flags 0x%x\n",
   494	                                      ndr->flags & LIBNDR_STRING_FLAGS);
   495	        }
   496	        
   497	        ndr->flags = saved_flags;
   498	        return NDR_ERR_SUCCESS;
   499	}
